import { createMetadata } from "@/lib/seo/metadata";
import { JsonLd, breadcrumbSchema } from "@/lib/seo/jsonld";
import { SITE_CONFIG } from "@/lib/constants/site";
import { GradientPageBg } from "@/components/shared/page-bg";
import { ServiceHero } from "@/components/services/service-hero";
import { ServicePainPoints } from "@/components/services/service-pain-points";
import { ServiceCapabilities } from "@/components/services/service-capabilities";
import { ServicePlatforms } from "@/components/services/service-platforms";
import { ServiceProcess } from "@/components/services/service-process";
import { OurWorksCta } from "@/components/our-works/our-works-cta";
import { BetaCta } from "@/components/shared/beta-cta";

export const metadata = createMetadata({
  title: "White Label Web Development Services for Agencies | Boldteq",
  description:
    "Boldteq provides reliable, senior-level web development as part of a single monthly subscription — delivered under your brand, built for agency workflows.",
  path: "/services/website-development",
});

const breadcrumbs = breadcrumbSchema([
  { name: "Services", path: "/services/website-development" },
  { name: "Web Development", path: "/services/website-development" },
]);

const serviceSchema = {
  "@context": "https://schema.org",
  "@type": "Service",
  name: "White Label Web Development",
  serviceType: "Web Development",
  description:
    "Senior-level web development as part of a single monthly subscription — delivered under your brand, built for agency workflows.",
  provider: {
    "@type": "Organization",
    name: SITE_CONFIG.name,
    url: SITE_CONFIG.url,
  },
  areaServed: "Worldwide",
  audience: {
    "@type": "BusinessAudience",
    audienceType: "Digital Agencies",
  },
};

export default function WebsiteDevelopmentPage() {
  return (
    <>
      <JsonLd data={breadcrumbs} id="schema-breadcrumbs" />
      <JsonLd data={serviceSchema} id="schema-service" />
      <GradientPageBg />
      <ServiceHero />
      <ServicePainPoints />
      <ServiceCapabilities />
      <ServicePlatforms />
      <ServiceProcess />
      <OurWorksCta />
      <BetaCta />
    </>
  );
}

import styles from "./service-pain-points.module.css";

const PAIN_POINTS = [
  {
    icon: "⏱️",
    title: "Deadlines Slip",
    text: "Dev bottlenecks delay launches. Clients notice. Relationships erode.",
  },
  {
    icon: "⚠️",
    title: "Quality Drops",
    text: "No two freelancers deliver the same standard — inconsistency kills agency credibility.",
  },
  {
    icon: "🐢",
    title: "Slow Hiring",
    text: "Recruiting, onboarding, tools, salaries — all before a single line of code ships.",
  },
  {
    icon: "🛡️",
    title: "Client Trust at Risk",
    text: "Every late delivery, every buggy handoff chips away at your agency's reputation.",
  },
];

export function ServicePainPoints() {
  return (
    <section className={styles["section"]}>
      <div className={styles["container"]}>
        {/* Header */}
        <div className={styles["header"]}>
          <div className={styles["badgeRow"]}>
            <div className={styles["badge"]}>
              <span className={styles["badgeText"]}>Why Agencies Struggle</span>
            </div>
          </div>
          <h2 className={styles["heading"]}>
            Why Web Development Becomes a Bottleneck as You Grow
          </h2>
          <p className={styles["subtitle"]}>
            As agencies scale, web development becomes the hardest part to
            manage. The usual options all come with trade-offs that limit your
            growth.
          </p>
        </div>

        {/* Cards */}
        <div className={styles["grid"]}>
          {PAIN_POINTS.map((point) => (
            <div key={point.title} className={styles["card"]}>
              <span
                className={styles["icon"]}
                role="img"
                aria-label={point.title}
              >
                {point.icon}
              </span>
              <h3 className={styles["cardTitle"]}>{point.title}</h3>
              <p className={styles["cardText"]}>{point.text}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

