  display: inline-flex;
  align-items: center;
}

.badgeText {
  margin: 0;
  font-size: 12px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-weight: 600;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.heading {
  color: var(--color-brand-navy);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 16px;
}

.subtitle {
  color: var(--color-text-subtle);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  line-height: 1.75;
}

/* Steps grid — 4 columns */
.stepsGrid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  grid-column-gap: 40px;
  grid-row-gap: 40px;
  align-self: stretch;
}

.step {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  padding: 0;
  position: relative;
}

/* white-round wrapper */
.numberCircle {
  z-index: 3;
  background-color: #fff;
  border-radius: var(--radius-pill);
  margin-bottom: 15px;
  position: relative;
  display: flex;
}

/* sky-digit inside white-round */
.number {
  z-index: 3;
  text-align: center;
  -webkit-text-fill-color: transparent;
  background-color: #fff;
  background-image: linear-gradient(#21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
  border: 1px dashed var(--color-text-primary);
  border-radius: var(--radius-pill);
  flex: 0 auto;
  justify-content: center;
  align-self: auto;
  align-items: center;
  width: 65px;
  height: 65px;
  margin-top: 0;
  margin-bottom: 0;
  padding: 5px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1.53rem;
  font-weight: 700;
  display: flex;
  position: static;
}

.stepTitle {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 25px;
  margin-bottom: 10px;
  text-align: center;
}

.stepText {
  color: var(--color-text-secondary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1.125rem;
  line-height: 28px;
  margin: 0;
  text-align: center;
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .stepsGrid {
    grid-template-columns: 1fr 1fr;
  }

  .heading {
    font-size: 34px;
    line-height: 40px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .stepsGrid {
    grid-template-columns: 1fr 1fr;
    grid-column-gap: 20px;
    grid-row-gap: 20px;
  }

  .header {
    margin-bottom: 36px;
  }

  .heading {
    font-size: 28px;
    line-height: 36px;
  }
}

/* ============================================================
   max-width: 479px
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding: 48px 1.25rem 56px;
  }

  .stepsGrid {
    grid-template-columns: 1fr;
  }

  .heading {
    font-size: 1.5rem;
    line-height: 1.3;
  }
}

