/* ============================================================
   SERVICE HERO — service-hero.module.css
   ============================================================ */

.section {
  background-color: transparent;
  padding-top: 4rem;
  padding-bottom: 4rem;
  font-weight: 400;
  text-decoration: none;
  position: relative;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* Badge */
.badgeRow {
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
}

.badge {
  background-color: rgba(33, 207, 255, 0.07);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  padding: 0 14px;
  line-height: 34px;
  display: inline-flex;
  align-items: center;
}

.badgeText {
  margin: 0;
  font-size: 12px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-weight: 600;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Heading */
.heading {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  line-height: 1.15;
  text-align: center;
  margin: 0 auto 20px;
  max-width: 860px;
}

/* Subtitle */
.subtitle {
  color: rgba(255, 255, 255, 0.7);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 18px;
  line-height: 1.7;
  text-align: center;
  max-width: 680px;
  margin: 0 auto 40px;
}

/* Stat badges row */
.statsRow {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
  margin-bottom: 44px;
}

.statBadge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background-color: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 40px;
  padding: 8px 16px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  color: #fff;
  white-space: nowrap;
}

.statIcon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

/* CTA row */
.ctaRow {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.primaryBtn {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  background-image: url('/images/webflow/Group-46729-2.svg'),
    linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  box-shadow: var(--shadow-card);
  transition: filter 0.2s;
}

.primaryBtn:hover {
  filter: brightness(1.1);
}

.secondaryBtn {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  font-weight: 600;
  background: transparent;
  border: 2px solid rgba(255, 255, 255, 0.25);
  border-radius: 0.75rem;
  padding: 0.75rem 1.5rem;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  transition: border-color 0.2s, background 0.2s;
}

.secondaryBtn:hover {
  border-color: rgba(255, 255, 255, 0.5);
  background: rgba(255, 255, 255, 0.06);
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .section {
    padding: 60px 5% 70px;
  }

  .subtitle {
    font-size: 16px;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .section {
    padding: 50px 5% 60px;
  }

  .statsRow {
    gap: 8px;
    margin-bottom: 32px;
  }

  .statBadge {
    font-size: 13px;
    padding: 7px 12px;
  }

  .ctaRow {
    flex-direction: column;
    align-items: stretch;
  }

  .primaryBtn,
  .secondaryBtn {
    justify-content: center;
    text-align: center;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding: 40px 1.25rem 50px;
  }

  .heading {
    font-size: 1.625rem;
  }

  .subtitle {
    font-size: 0.9375rem;
  }
}

